-- V3: (re)cria a tabela usuarios com id BIGINT autoincremental (IDENTITY).
--
-- Por que DROP + CREATE?
--   Em um banco novo, a V2 cria usuarios com id UUID; no banco local a tabela nao existe.
--   DROP IF EXISTS + CREATE deixa os dois cenarios no mesmo estado final.
--   ATENCAO: apaga usuarios existentes. Decisao tomada porque nenhum ambiente tem usuarios reais.
--
-- Por que GENERATED BY DEFAULT AS IDENTITY?
--   O banco gera o id (Hibernate usa GenerationType.IDENTITY). BY DEFAULT ainda aceita
--   id informado manualmente (seeds/testes) - nesse caso a sequencia NAO avanca.
--
-- login UNIQUE + NOT NULL: findByLogin precisa retornar no maximo um usuario.

DROP TABLE IF EXISTS usuarios;

CREATE TABLE usuarios (
    id    BIGINT       GENERATED BY DEFAULT AS IDENTITY,
    login VARCHAR(255) NOT NULL,
    senha VARCHAR(255) NOT NULL,
    CONSTRAINT usuarios_pkey     PRIMARY KEY (id),
    CONSTRAINT usuarios_login_uk UNIQUE (login)
);
